package org.fossify.keyboard.helpers

import android.content.Context

/**
 * Resolves the municipality codes stored on CNS cards (codice catastale like "H501", or the numeric ISTAT code)
 * to the municipality name, using assets/comuni.tsv generated by scripts/update_comuni.py from ISTAT data.
 */
object Comuni {
    private var names: Map<String, String>? = null

    @Synchronized
    private fun load(context: Context): Map<String, String> {
        names?.let { return it }
        val map = HashMap<String, String>()
        context.assets.open("comuni.tsv").bufferedReader().useLines { lines ->
            lines.forEach { line ->
                val columns = line.split('\t')
                if (columns.size >= 3) {
                    map[columns[0]] = columns[2]
                    map[columns[1]] = columns[2]
                }
            }
        }
        names = map
        return map
    }

    fun nameFromCode(context: Context, code: String): String? {
        var key = code.trim().uppercase()
        if (key.isNotEmpty() && key.all { it.isDigit() } && key.length < 6) {
            key = key.padStart(6, '0')
        }
        return load(context)[key]
    }
}
